// Parse Query v3 - supporte equation PubMed personnalisee de l'utilisateur
const data = $input.all()[0].json;
const question = data.question || '';
const criteria = data.criteria || '';
const prefilter_enabled = data.prefilter_enabled !== undefined ? data.prefilter_enabled : true;
const prefilter_count = parseInt(data.prefilter_count) || 300;
const max_results = parseInt(data.max_results) || 1000;
// INCLUDE_EXTRACTION_PREDATORY_v1 - flags v0.2.6
const include_extraction = data.include_extraction === true || data.include_extraction === 'true';
const include_predatory_scan = data.include_predatory_scan === true || data.include_predatory_scan === 'true';

// LA CADENCE, JETEE DEPUIS TOUJOURS SUR CE CHEMIN. `proxy._injecter_la_cadence` la pose dans
// le corps de tout lancement, mais « Extract Params » est un noeud de mise en forme qui ne
// recopie que ses champs nommes (`includeOtherFields: false`) : `pacing_ms` n'en ressortait
// pas. « Prepare Batches » lit alors `(articles[0] || {})._pacing_ms`, ne trouve rien, et pose
// un intervalle de ZERO entre deux appels au modele. On relit donc la valeur dans le corps du
// declencheur, comme ce noeud le fait deja pour `direct_articles`.
let _pacing = data.pacing_ms;
if (_pacing === undefined) {
  try { var _wb2 = $('User Input').first().json.body || $('User Input').first().json; _pacing = _wb2 ? _wb2.pacing_ms : undefined; } catch (e) { _pacing = undefined; }
}
const pacing_ms = (_pacing === undefined || _pacing === null) ? undefined : Number(_pacing);

const customPubmed = (data.custom_pubmed_query || '').trim();
  // DIRECT_ARTICLES_BYPASS_v2 - Extract Params (Set) ne propage pas direct_articles ;
  // on le lit directement depuis le body du webhook 'User Input' (source de verite).
  let _da = data.direct_articles;
  if (!Array.isArray(_da)) {
    try { var _wb = $('User Input').first().json.body || $('User Input').first().json; _da = _wb ? _wb.direct_articles : null; } catch (e) { _da = null; }
  }
  const direct_articles = Array.isArray(_da) ? _da : null;



let pubmed_query = question;
let openalex_query = question;
let crossref_query = question;

// Helper: derive simple keyword query from a PubMed boolean equation
function derivePlainQuery(pmQuery) {
  if (!pmQuery) return question;
  // strip MeSH/field tags like [MeSH Terms], [tiab], [Title/Abstract]
  let q = pmQuery.replace(/\[[^\]]*\]/g, ' ');
  // remove parentheses
  q = q.replace(/[()]/g, ' ');
  // remove quotes
  q = q.replace(/["']/g, ' ');
  // collapse boolean operators (keep AND/OR meaning by joining with space)
  q = q.replace(/\b(AND|OR|NOT)\b/gi, ' ');
  // collapse multiple spaces
  q = q.replace(/\s+/g, ' ').trim();
  return q || question;
}

if (customPubmed) {
  // === MODE EQUATION PERSONNALISEE ===
  pubmed_query = customPubmed;
  openalex_query = derivePlainQuery(customPubmed);
  crossref_query = derivePlainQuery(customPubmed);
  console.log('Parse Query: USING CUSTOM PUBMED EQUATION');
  console.log('  PubMed: ' + pubmed_query.substring(0, 100));
  console.log('  OpenAlex (derived): ' + openalex_query.substring(0, 80));
} else {
  // === MODE GENERATION OLLAMA ===
  try {
    const raw = data.ollama_response || '';
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed.pubmed_query) pubmed_query = parsed.pubmed_query;
    if (parsed.openalex_query) openalex_query = parsed.openalex_query;
    if (parsed.crossref_query) crossref_query = parsed.crossref_query;
    console.log('Parse Query: Ollama-generated queries extracted');
  } catch(e) {
    console.log('Parse Query: Ollama parse error, using question as fallback - ' + e.message);
  }
}

// PER_BASE_QUERY_PIPELINE_v1 - traduction deterministe par base depuis l'equation PubMed
function buildBaseQueries(pmq) {
  var raw = (pmq || '').trim();
  var s = raw.replace(/\(\s*"?\d{4}"?\s*\[[^\]]*\]\s*:\s*"?\d{4}"?\s*\[[^\]]*\]\s*\)/gi, ' ');
  var bool = s.replace(/\[[^\]]*\]/g, ' ').replace(/\b(and|or|not)\b/g, function(m){ return m.toUpperCase(); }).replace(/\(\s*\)/g, ' ').replace(/\s+/g, ' ').trim().replace(/^\s*(AND|OR|NOT)\b/, '').replace(/\b(AND|OR|NOT)\s*$/, '').trim();
  var free = bool.replace(/[()]/g, ' ').replace(/\b(AND|OR|NOT)\b/g, ' ').replace(/\s+/g, ' ').trim();
  return { boolean: bool, freetext: free };
}
var _bq = buildBaseQueries(pubmed_query);
openalex_query = _bq.freetext;
crossref_query = _bq.freetext;
var doaj_query = _bq.boolean;
var base_query = _bq.boolean;
var lens_query = _bq.boolean;
var semantic_query = _bq.freetext;
var __dm = (pubmed_query||'').match(/"?(\d{4})"?\s*\[[^\]]*\]\s*:\s*"?(\d{4})"?\s*\[[^\]]*\]/i);
var date_start = __dm ? __dm[1] : '';
var date_end = __dm ? __dm[2] : '';

const topic = question.substring(0, 50).replace(/[^a-zA-Z0-9 ]/g, '').trim();
const folderName = (topic || 'untitled') + ' review ultralab';
const folderPath = '/desktop/' + folderName;

// LE MOTIF DE REFUS DU RUN PRECEDENT EST RETIRE ICI, AU PREMIER NOEUD DU FLUX (2026-09-18).
//
// POURQUOI PAS DANS « Relire Corpus », OU IL ETAIT ECRIT. Mesure du 2026-09-18, les voies de
// reussite jouees UNE PAR UNE sur le vrai enchainement, deux runs de suite dans le meme dossier :
//   - « IF Skip Screening » sortie 0 va droit a « IF Skip PDF » : un run SANS TRI ne traverse
//     jamais « Relire Corpus » ;
//   - quand l'ecriture du corpus echoue, « Ecrire Corpus » rend ses articles et « Relire Corpus »
//     sort a « aucun chemin annonce » AVANT le retrait.
// Dans ces deux etats le run REUSSIT et ecrit son rapport dans le MEME dossier (son nom ne depend
// que du sujet), et ECHEC-FAILED.txt y restait lisible, avec les chiffres du run precedent et sa
// phrase « aucun rapport produit ».
//
// QUATRE PLACEMENTS ONT ETE JOUES SUR SIX ETATS AVANT D'ECRIRE CETTE LIGNE : ici ; dans le noeud
// qui ecrit le rapport ; les deux ; et celui d'avant ce tour, dans « Relire Corpus ». Le retrait
// ICI est le seul qui, A LUI SEUL, ne laisse jamais lire le motif d'un AUTRE run : le retrait
// dans le noeud qui ecrit le rapport couvre bien les trois voies de reussite, mais pas le second
// refus dont le depot echoue, et il en faudrait alors deux, dans deux fichiers.
//
// CE NOEUD EST TRAVERSE PAR TOUS LES RUNS DE CETTE CHAINE, et cela se LIT dans le fichier :
// « User Input » mene a « IF Custom Query », qui mene a « Extract Params » directement ou par
// « Call Ollama », et « Extract Params » ne mene qu'ici. Aucune autre voie n'existe.
//
// LE RETRAIT NE PEUT PAS FAIRE ECHOUER CE NOEUD : l'appel au module est DANS l'enveloppe. Et la
// cible ne peut pas viser une racine : folderPath commence par '/desktop/' et porte toujours un
// nom de dossier, meme sans sujet (« untitled review ultralab »).
try {
  require('fs').unlinkSync(folderPath + '/ECHEC-FAILED.txt');
  console.log('Parse Query: motif de refus du run precedent retire');
} catch (eMotifRC) {}

const skip_ranking = data.skip_ranking || false;
const skip_clustering = data.skip_clustering || false;
const skip_screening = data.skip_screening || false;
const skip_pdf = data.skip_pdf || false;
const output_format = ((data.output_format || 'ris') + '').toLowerCase();

console.log('Parse Query output: question=' + question.substring(0, 40) + ', folder=' + folderName);
console.log('Skip flags: ranking=' + skip_ranking + ' clustering=' + skip_clustering + ' screening=' + skip_screening + ' pdf=' + skip_pdf);

return [{ json: {
    direct_articles: direct_articles,

  question,
  criteria,
  search_query: openalex_query,
  pubmed_query,
  openalex_query,
  crossref_query,
  doaj_query,
  base_query,
  lens_query,
  semantic_query,
  date_start,
  date_end,
  output_folder: folderPath,
  folder_name: folderName,
  prefilter_enabled,
  prefilter_count,
  max_results,
  skip_ranking,
  skip_clustering,
  skip_screening,
  skip_pdf,
  include_extraction,
  include_predatory_scan,
  pacing_ms,
  custom_query_used: !!customPubmed,
  output_format
}}];

// CORPUS_RELU_APRES_TRI_v1 (2026-09-20). LES ARTICLES REVIENNENT DANS LE FLUX APRES LE TRI.
//
// CE QUI ETAIT CASSE. Depuis le 2026-08-25 (le corpus ne traverse plus la frontiere) le
// sous-workflow de tri ecrit le corpus sur le disque et ne rend QU'UN element, porteur du seul
// chemin. L'orchestrateur ne relisait pas ce fichier. Mesure du 2026-09-20 sur les vrais
// noeuds, configuration par defaut (skip_pdf faux) : la recuperation des PDF filtre sur
// `screening_decision`, ne trouve ce champ sur aucun element, et rend 0 element. Aucun noeud
// en aval ne s'execute : ni export, ni methods.json, ni PRISMA_Report.html. Un run avec tri ne
// produisait donc AUCUN rapport. Avec skip_pdf vrai, l'export recevait a la place 1 article
// fantome sans titre, et la ligne « Records screened » du flux valait 1 pour 18 references.
//
// POURQUOI ICI, ET PAS DANS LE SOUS-WORKFLOW. Les deux voies ont ete mesurees avant que ce
// noeud soit ecrit, sur 12 772 references (l'effectif du run mort le 2026-08-20) :
//   - faire traverser les articles la frontiere du sous-workflow represente 17 670 042 octets
//     contre 311, soit 56 817 fois plus, et le moteur RECOPIE les elements a ce passage
//     (22,4 Mo de tas par copie, tenue deux fois). C'est la mesure meme qui a impose
//     l'ecriture par fichier ;
//   - le noeud d'assemblage du module CESSE de relire le fichier des qu'on lui rend les
//     articles (mesure directe sur ce vrai noeud, sa trace « Corpus relu depuis » disparait) :
//     il retomberait sur le chemin d'avant le 2026-08-25.
// On relit donc ici, une seule fois, du cote de l'appelant.
//
// CE NOEUD NE VOIT NI LE CHEMIN SANS TRI, qui ne passe pas par lui, NI LE CHEMIN DU MODULE,
// qui a son propre assemblage. Le REPLI du noeud d'ecriture est rendu tel quel.
const _fsRC = require('fs');
const _elemsRC = $input.all();
const _e0RC = (_elemsRC[0] && _elemsRC[0].json) || {};
const _cheminRC = String(_e0RC._corpus_fichier || '');
// UN ZERO ANNONCE N'EST PAS UNE ABSENCE D'ANNONCE (2026-09-18 ; carnet : « zero pris pour une
// absence »). `Number(x || 0)` rendait 0 pour une clef MANQUANTE comme pour un effectif NUL : le
// motif depose aurait chiffre « 0 reference(s) annoncee(s) » pour une annonce qui n'a pas eu lieu,
// dans les deux langues, et bloque le run sur ce mensonge. Les deux etats sont distingues ici, et
// ils ne portent pas le meme refus. Etat que le producteur d'aujourd'hui n'atteint pas
// (« Ecrire Corpus » pose `_corpus_fichier` et `_corpus_n` dans le MEME objet, `_corpus_n` valant
// `_elements.length`) : c'est ce que le noeud PUBLIE sur une annonce qu'il ne maitrise pas.
const _brutNRC = _e0RC._corpus_n;
const _annonceRC = (_brutNRC === undefined || _brutNRC === null || _brutNRC === ''
  || isNaN(Number(_brutNRC))) ? null : Number(_brutNRC);
// CE QUE LE MOTIF DIT DE L'ANNONCE, dans les deux langues.
const _ANNONCE_FR = (_annonceRC === null)
  ? 'aucun effectif annoncé' : (_annonceRC + ' référence(s) annoncée(s)');
const _ANNONCE_EN = (_annonceRC === null)
  ? 'no record count announced' : (_annonceRC + ' record(s) announced');

// LE REFUS DOIT ATTEINDRE L'UTILISATEUR, ET LES QUATRE CANAUX ONT ETE MESURES AVANT CE REMEDE
// (2026-09-20, sur les vraies routes et le vrai registre) :
//   1. LA REPONSE AU WEBHOOK est deja rendue quand ce noeud travaille : la branche
//      « User Input » -> « Build Async Response Pipeline » -> « Respond Immediately Pipeline »
//      repond « started » et renvoie l'appelant vers /api/last-result. Elle ne porte aucun motif ;
//   2. /api/last-result?mode=pipeline rend « Aucun dossier de resultat trouve sur le Bureau »
//      MEME pour un run REUSSI qui a ecrit son resume : la route ne garde que les dossiers dont le
//      NOM contient le mode, et le dossier de cette chaine s'appelle « <sujet> review ultralab ».
//      Sans ce filtre, le meme dossier est trouve. Aucun noeud n'ecrit summary.json ;
//   3. LES FICHIERS DU DOSSIER DE SORTIE sont, eux, servis a l'utilisateur : la route qui liste
//      les fichiers d'un run rend un .txt du dossier, et celle qui les ouvre le sert (code 200).
//      C'est le SEUL canal que ce noeud puisse atteindre ;
//   4. LE JOURNAL DU REGISTRE NE CONNAIT PAS CE RUN. Le relais n'enregistre que les lancements
//      dont le chemin porte « ultralab-module » : a corps identique, 0 run enregistre pour le
//      webhook de cette chaine, 1 pour celui d'un module. Et le tri declare son etape sous le mode
//      « screening » (aucun noeud de l'orchestrateur ne pose `_module_mode` ; mesure du
//      2026-09-18 sur les 21 fichiers de workflows, code et commentaires separes noeud par noeud
//      par l'analyseur syntaxique : 22 occurrences AILLEURS, module 15, tri 6, bouturage 1, et
//      dans CE fichier 0 dans du code et une seule en tout, celle de cette phrase ; les deux
//      seuls noeuds qui la POSENT sont « Prepare Articles » du module, qui la tire du mode
//      demande, et « Ecrire Corpus » du tri, qui se contente de la recopier), si bien que sa
//      declaration marque un run de MODULE etranger : mesure, le motif « Dernier noeud dans lequel
//      il est entre : Double Screen Kappa » se colle a un run qui n'a rien a voir, et seulement au
//      bout de 45 minutes. DECLARER UNE ETAPE ICI AGGRAVERAIT CE DEFAUT au lieu de le corriger :
//      on accuserait un innocent, ce que le registre dit lui-meme ne plus vouloir faire.
// On depose donc le motif, entier et dans les deux langues, dans le dossier du run.
const _DOSSIER_RC = _cheminRC.replace(/\/[^\/]*$/, '');
const _FICHIER_RC = 'ECHEC-FAILED.txt';
function _refusRC(codeRC, frRC, enRC) {
  try {
    _fsRC.mkdirSync(_DOSSIER_RC, { recursive: true });
    _fsRC.writeFileSync(_DOSSIER_RC + '/' + _FICHIER_RC,
      'ÉCHEC DU RUN / RUN FAILED\n'
      + 'Nœud / node : Relire Corpus\n'
      + 'Code : ' + codeRC + '\n'
      + 'Date / date : ' + new Date().toISOString() + '\n\n'
      + 'FR : ' + frRC + '\n'
      + 'EN : ' + enRC + '\n', 'utf-8');
    console.log('[Relire Corpus] motif depose : ' + _DOSSIER_RC + '/' + _FICHIER_RC);
  } catch (eDRC) {
    // LE DEPOT NE PEUT PAS FAIRE PERDRE LE REFUS : il est un confort, le refus est la regle.
    console.log('[Relire Corpus] motif non depose (' + eDRC.message + ')');
  }
  return new Error(codeRC + ' | FR : ' + frRC + ' | EN : ' + enRC);
}
if (!_cheminRC) {
  // Aucun corpus annonce : le tri a rendu les articles lui-meme (repli d'ecriture).
  console.log('[Relire Corpus] aucun chemin annonce : ' + _elemsRC.length
    + ' element(s) rendus tels quels');
  return _elemsRC;
}
// LE MOTIF DU RUN PRECEDENT N'EST PLUS RETIRE ICI, ET C'EST MESURE (2026-09-18).
//
// DEFAUT : le dossier de sortie porte un nom FIXE, que « Parse Query » ecrit
// `(topic || 'untitled') + ' review ultralab'`, sans identifiant de run ni horodatage. Un run
// refuse y depose son motif ; l'utilisateur corrige son corpus et relance le MEME sujet ; le run
// REUSSIT, ecrit son rapport, et le motif d'echec reste a cote avec ses chiffres perimes et sa
// phrase « aucun rapport produit ». Or c'est le SEUL canal par lequel l'echec de cette chaine
// atteint l'utilisateur : le rendre menteur coute plus cher que de n'avoir rien dit.
//
// CE NOEUD NE POUVAIT PAS PORTER LE REMEDE, et les voies de reussite ont ete jouees UNE PAR UNE
// pour l'etablir : un run SANS TRI ne passe pas par lui (« IF Skip Screening » sortie 0 va droit
// a « IF Skip PDF »), et un run dont l'ECRITURE du corpus a echoue sort quinze lignes plus haut,
// a « aucun chemin annonce ». Le retrait est donc ecrit dans « Parse Query », premier noeud du
// flux, que TOUTES les voies traversent ; le detail de la mesure y est.
//
// L'IDENTIFIANT DE RUN, autre remede possible, est MESURE IMPOSSIBLE ICI : le relais n'enregistre
// que les lancements dont le chemin porte « ultralab-module », donc aucun run de cette chaine
// n'existe au registre, et le nom du dossier n'en porte aucun. L'INSTANT, lui, est ecrit dans le
// motif : la route qui liste les fichiers d'un run ne rend que le nom, l'extension, la taille et
// le fait d'etre consultable (mesure sur src/server.py), jamais une date ; sans cet instant, un
// motif pose a cote du rapport d'un run PRECEDENT ne se date par rien.
let _brutRC;
try {
  _brutRC = _fsRC.readFileSync(_cheminRC, 'utf-8');
} catch (eRC) {
  // REFUS NOMME. Un run qui a perdu son corpus doit le DIRE : sans ce refus, la recuperation
  // des PDF rendait 0 element et la chaine s'arretait sans une ligne de journal.
  throw _refusRC('corpus_absent',
    'le corpus du tri est introuvable ou illisible (' + _cheminRC + ') : ' + eRC.message
    + '. Le tri : ' + _ANNONCE_FR + ' ; aucun rapport produit.',
    'the screening corpus cannot be found or read (' + _cheminRC + '): ' + eRC.message
    + '. Screening: ' + _ANNONCE_EN + '; no report produced.');
}
let _articlesRC = null;
try { _articlesRC = JSON.parse(_brutRC); } catch (eRC2) { _articlesRC = null; }
const _reluRC = Array.isArray(_articlesRC) ? _articlesRC.length : 0;
if (_reluRC === 0) {
  // REFUS NOMME. Le noeud d'ecriture ne rend un chemin que pour au moins une reference : zero
  // reference relue signale un fichier tronque ou remplace, jamais un corpus legitime.
  throw _refusRC('corpus_illisible',
    'le corpus du tri ne se lit pas comme une liste de références (' + _cheminRC + ', '
    + _brutRC.length + ' octets). Le tri : ' + _ANNONCE_FR + ', '
    + _reluRC + ' relue(s) ; aucun rapport produit.',
    'the screening corpus does not read as a list of records (' + _cheminRC + ', '
    + _brutRC.length + ' bytes). Screening: ' + _ANNONCE_EN + ', '
    + _reluRC + ' read back; no report produced.');
}
// L'EFFECTIF RELU EST COMPARE A L'EFFECTIF ANNONCE (2026-09-20).
//
// DEFAUT MESURE LE MEME JOUR, chaine entiere sur les vrais noeuds : le corpus annonce 18
// references, le fichier est remplace par une liste VALIDE de 5, et rien ne refusait. Le rapport
// publiait « Records screened (AI pre-screening) » = 5 et methods.json articles_processed = 5,
// PENDANT QUE le meme methods.json declarait 18 paires jugees par deux relecteurs : 18 paires
// parmi 5 references traitees. Meme silence a 20 pour 18 annoncees. C'est exactement le symptome
// que ce noeud existe pour supprimer, reproduit a travers lui.
//
// ATTEIGNABLE : le corpus est ecrit au chemin FIXE <output_folder>/articles-full.json, et
// output_folder ne depend que du sujet, sans identifiant de run ni horodatage (« Parse Query » :
// folderName = (topic || 'untitled') + ' review ultralab'). Deux runs du meme sujet partagent donc
// le meme fichier.
//
// DEUX GRANDEURS DE CE MEME ELEMENT NE SONT LUES PAR PERSONNE, ET CE NOEUD EST L'ENDROIT OU ON
// LES CHERCHERAIT (declaration, 2026-09-18). Mesure du meme jour sur TOUT le depot, les clefs
// comptees avec leur frontiere de mot : `_double_resume` et `_double_relecture` paraissent CHACUN
// DEUX fois, l'une dans « Double Screen Kappa » du tri, qui les ECRIT, l'autre dans cette
// declaration. Aucun lecteur, nulle part. Un premier comptage par SOUS-CHAINE annoncait 16
// occurrences pour la seconde : il prenait le nom de fonction `paires_double_relecture` de
// src/run_resume.py pour la clef. Reste ouvert : leur donner un lecteur, ou cesser de les
// produire. Ce lot ne tranche pas, faute de mesure sur ce qu'un lecteur en ferait.
//
// LA GARDE « EFFECTIF ANNONCE SUPERIEUR A ZERO » A ETE RETIREE (2026-09-20) : elle etait VRAIE
// PARTOUT OU ELLE ETAIT EVALUEE, donc elle ne protegeait aucun etat (carnet : « cas protege deux
// fois », dont le remede est de retirer la protection morte, pas de lui inventer un cas). Mesure
// sur le code du producteur, tous ses chemins enumeres : « Ecrire Corpus » ne rend un chemin que
// dans la branche qui vient d'ecrire, et il y pose `_corpus_fichier` et `_corpus_n` DANS LE MEME
// OBJET, `_corpus_n` valant `_elements.length` ; sur zero element, `output_folder` est vide, la
// garde de chemin refuse, et le noeud rend ses elements sans annoncer aucun chemin. Les trois
// `return` de « Double Screen Kappa » recopient l'element d'entree tel quel. Un chemin annonce
// porte donc toujours un effectif d'au moins 1. Ce qui CHANGE si un producteur futur annonce un
// chemin sans effectif lisible : le refus est leve au lieu du silence, ce qui est le bon sens du
// defaut.
//
// L'EGALITE STRICTE NE PEUT PAS REFUSER A TORT, et c'est mesure sur le VRAI producteur, pas
// deduit : « Ecrire Corpus » ecrit `_elements.map(...)` et annonce `_corpus_n = _elements.length` ;
// « Double Screen Kappa » reecrit `out`, qui est `pass1.map(...)`, donc de meme longueur, et laisse
// la premiere passe en place si sa reecriture echoue. Mesure du 2026-09-20 sur la chaine entiere :
// annonce et ecrit sont egaux sur 18 paires, 12 paires d'une seule categorie, 1 paire, double
// relecture desactivee, et reecriture impossible. Le REPLI d'ecriture, lui, n'annonce AUCUN chemin
// et sort plus haut : aucun refus n'y est possible.
if (_annonceRC === null) {
  // REFUS NOMME, DISTINCT DU PRECEDENT : une annonce ABSENTE n'est pas une annonce a ZERO, et le
  // motif ne doit pas chiffrer une annonce qui n'a pas eu lieu.
  throw _refusRC('effectif_non_annonce',
    'le corpus du tri est annoncé sans son effectif (' + _cheminRC + ') : ' + _reluRC
    + ' référence(s) relue(s), aucun effectif annoncé à comparer'
    + ' ; aucun rapport produit.',
    'the screening corpus is announced without its record count (' + _cheminRC + '): ' + _reluRC
    + ' record(s) read back, no announced count to compare; no report produced.');
}
if (_reluRC !== _annonceRC) {
  throw _refusRC('corpus_incomplet',
    'le corpus du tri ne porte pas l\'effectif annoncé (' + _cheminRC + ') : ' + _ANNONCE_FR
    + ', ' + _reluRC + ' relue(s) ; aucun rapport produit.',
    'the screening corpus does not hold the announced number of records (' + _cheminRC + '): '
    + _ANNONCE_EN + ', ' + _reluRC + ' read back; no report produced.');
}
console.log('[Relire Corpus] ' + _reluRC + ' reference(s) relues depuis ' + _cheminRC
  + ' (annoncees : ' + _annonceRC + ')');
return _articlesRC.map(function (aRC) { return { json: aRC }; });

const data = $input.all()[0].json;
const articles = data.articles || [];
const stats = data.prisma_stats || data.stats || {};
const outputFolder = data.output_folder || '/desktop/review ultralab';

const sorted = [...articles].sort((a, b) => (b.score || 0) - (a.score || 0));
const included = sorted.filter(a => a.screening_decision === 'Include');
const maybe = sorted.filter(a => a.screening_decision === 'Maybe');
const excluded = sorted.filter(a => a.screening_decision === 'Exclude');

const screening_summary = sorted.map(a => ({
  title: a.title || '',
  authors: Array.isArray(a.authors) ? a.authors.join('; ') : '',
  year: a.year || '',
  journal: a.journal || '',
  doi: a.doi || '',
  abstract: (a.abstract || '').substring(0, 500),
  source: a.source || '',
  score: a.score !== undefined ? a.score : 50,
  cluster: a.cluster_label || '',
  decision: a.screening_decision || 'Maybe',
  color: a.screening_color || 'orange',
  reason: a.screening_reason || ''
}));

return [{
  json: {
    status: 'completed',
    output_folder: outputFolder,
    prisma_stats: {
      total: stats.total || articles.length,
      included: stats.included || included.length,
      excluded: stats.excluded || excluded.length,
      maybe: stats.maybe || maybe.length
    },
    screening_summary
  }
}];

// === RESPOND IMMEDIATELY (async webhook pattern) ===
// Envoie une reponse rapide au browser pour qu'il puisse fermer la connexion HTTP
// et basculer sur le polling. Le workflow continue en parallele.
const input = $input.first().json;
const body = input.body || input;
const question = (body.question || '').toString();
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const timestamp = now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate()) + '-' + pad(now.getHours()) + pad(now.getMinutes());
// Le pipeline ecrit son dossier dans /desktop/<topic> review ultralab/
const topic = question.substring(0, 50).replace(/[^a-zA-Z0-9 ]/g, '').trim();
const expectedFolder = '/desktop/' + (topic || 'untitled') + ' review ultralab';
return [{
  json: {
    started: true,
    async: true,
    mode: 'pipeline',
    expected_folder: expectedFolder,
    started_at: now.toISOString(),
    message: 'Pipeline systematique demarre en background sur n8n. Le browser doit poller /api/last-result pour le resultat final.'
  }
}];

// Pipeline Predatory Scan - appelle Flask /api/predatory-check
// Idempotent et defensif : si Flask down, retourne les articles non scores
const items = $input.all();
const articles = items.map(i => i.json);
console.log('[Predatory Scan Pipeline] ' + articles.length + ' articles a scanner');

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8080/api/predatory-check',
    body: JSON.stringify({ articles: articles, do_external_apis: true }),
    headers: { 'Content-Type': 'application/json' },
    timeout: 1800000,
    json: true,
  });
  if (resp && resp.success && Array.isArray(resp.scanned)) {
    return resp.scanned.map(a => ({ json: a }));
  }
  console.log('[Predatory Scan] reponse Flask inattendue, articles non scores');
  return articles.map(a => ({ json: { ...a, _predatory_error: 'invalid flask response' } }));
} catch (e) {
  console.log('[Predatory Scan] erreur : ' + (e.message || e));
  return articles.map(a => ({ json: { ...a, _predatory_error: (e.message || String(e)) } }));
}
